# Kaggle GPU kernel generated by scripts/kaggle_run.py. Do not edit the copy on Kaggle; edit kaggle/kernel_template.py.
# Clones the repository at a pinned commit, rebuilds + verifies the data split, runs the listed experiment configs,
# and leaves runs/ (metrics, per-example probabilities; no text, no checkpoints) in /kaggle/working for download.
import json
import os
import subprocess
import sys
import time

COMMIT = "__COMMIT__"
CONFIGS = json.loads('__CONFIGS__')
REPO = "https://github.com/faizdevx/Multilingual-Mental-Health-Risk-.git"
WORK = "/kaggle/working"
os.environ["MHRISK_RUNS_DIR"] = f"{WORK}/runs"
os.environ.setdefault("HF_HUB_DISABLE_PROGRESS_BARS", "1")


def sh(cmd, check=True):
    print(f"\n$ {cmd}", flush=True)
    r = subprocess.run(cmd, shell=True)
    if check and r.returncode != 0:
        sys.exit(f"command failed ({r.returncode}): {cmd}")
    return r.returncode


t0 = time.time()
sh("nvidia-smi --query-gpu=name,memory.total --format=csv")
sh(f"git clone -q {REPO} /kaggle/repo && cd /kaggle/repo && git checkout -q {COMMIT} && git log --oneline -1")
os.chdir("/kaggle/repo")
sh("pip install -q -r requirements-colab.txt 2>&1 | tail -n 3")
sh("python scripts/download_data.py")
sh("python scripts/prepare_data.py > /dev/null")
sh("python scripts/freeze_splits.py --check")  # aborts the whole kernel if the split drifted
status = {}
for cfg in CONFIGS:
    rc = sh(f"python scripts/run_experiment.py {cfg}", check=False)  # one failing config doesn't kill the rest
    status[cfg] = rc
sh(f"python scripts/aggregate_runs.py --out {WORK}/results", check=False)
json.dump({"commit": COMMIT, "configs": status, "minutes": round((time.time() - t0) / 60, 1)},
          open(f"{WORK}/batch_status.json", "w"), indent=2)
print("BATCH DONE", status, flush=True)
